-- Research collection only; administrator and visit tables omitted.
CREATE TABLE `karya` (
  `id` int NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `seniman` varchar(255) NOT NULL,
  `tahun` varchar(50) DEFAULT NULL,
  `deskripsi` text,
  `gambar` varchar(255) DEFAULT NULL,
  `lebar` int DEFAULT NULL,
  `tinggi` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=38 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `karya` VALUES (18,'Doa di Bawah Bulan','Ahmad Saihu','2026','Sekelompok pemuda bertelanjang dada dengan topi kerucut berdiri di atas bebatuan malam, menengadah ke langit; satu di antaranya memegang bulan purnama di telapak tangan. Adegan surreal yang terasa seperti ritual doa atau harapan kolektif, dibingkai palet gelap dan cahaya biru kehijauan yang dramatis.','d4cb6706cabc669b0276940611c1b8f0.webp',1414,1920,'2026-08-22 01:09:43','2026-08-22 11:04:15'),(19,'Sisa di Tepi Air','Ahmad Saihu','2026','Dua perahu kayu terjebak di antara tumpukan sampah yang memenuhi tepian air. Digambar dengan pensil secara realistis dan penuh detail, karya ini merekam potret pencemaran lingkungan perairan sekaligus kehidupan nelayan kecil yang berdampingan dengan limbah.','2d13ea7ac5935667c08a2305d1911b26.webp',3060,2050,'2026-08-22 01:11:13','2026-08-22 09:22:39'),(20,'Coretan di Dinding','Hidayatullah Aini','2026','Seorang anak laki-laki berdiri dengan krayon merah di tangan, di depan dinding penuh coretan spontan hasil imajinasinya. Warna hangat berpadu dengan latar kamar bermain yang berantakan, menghadirkan potret kecil kebebasan berekspresi anak.','8947bab21ddb769ee441ce0fe7627cec.webp',1500,2245,'2026-08-22 01:12:08','2026-08-22 09:22:39'),(22,'Isi Hatimu','Hidayatullah Aini','2026','Sketsa pensil seorang pemuda memegang dua balon berbentuk hati yang terikat pada kotak bertuliskan \"mind\", dengan pesan \"Fill your heart, your thoughts will be lighter\" — mengisi hati dengan kebaikan akan meringankan beban pikiran.','2a5e7006d93fdd5842ea24b21e6c8db9.webp',1385,1920,'2026-08-22 01:23:10','2026-08-22 09:22:40'),(23,'Yang Menyaksikan','Ahmad Saihu','2024','Dua pria berjas berdiri membelakangi, mengamati beberapa perempuan berpakaian merah dengan bunga di rambut yang duduk bersimpuh di tengah reruntuhan senja. Komposisi warna dingin-hangat yang kontras menghadirkan ketegangan antara pengamat dan yang diamati.','b288b611b2973d9bf65326586f78a3cb.webp',1920,1385,'2026-08-22 01:24:29','2026-08-22 09:22:40'),(24,'Telinga Rimba','Ahmad Saihu','','Potret sesosok makhluk menyerupai manusia dengan telinga runcing melengkung seperti peri hutan, mata terpejam dalam damai. Latar abstrak hijau-abu memperkuat kesan magis dan tenang dari sosoknya.','dd401583301cf6189bd17422c38b6e43.webp',1280,1268,'2026-08-22 01:44:08','2026-08-22 09:22:40'),(25,'Rumah untuk Semua','Ahmad Saihu','2026','Kolase visual antara sketsa petani, cetak biru denah rumah sederhana, dan tumpukan karung \"Beras Bulog\". Karya ini merenungkan pangan dan tempat tinggal sebagai kebutuhan dasar yang seharusnya bisa dijangkau semua orang.','567a561f0442fb662801c84b05d97609.webp',1494,1920,'2026-08-22 01:45:24','2026-08-22 09:22:40'),(26,'Suara yang Tertahan','Ahmad Saihu','2026','Kumpulan wajah dan tubuh yang menjerit dari kegelapan, ekspresi intens dan mendesak. Repetisi wajah menciptakan efek paduan suara kepedihan yang menggema tanpa kata.','db948f1d47b88eee4b3509c8bae75ac4.webp',1080,1350,'2026-08-22 01:46:56','2026-08-22 11:04:15'),(27,'Barisan Panjang','Ahmad Saihu','2025','Sosok-sosok berpakaian pelindung putih berjalan beriringan dengan warga desa membawa bendera merah putih, diiringi sosok perempuan raksasa berjubah kuning di tengah kabut pegunungan. Palet warna cerah berpadu dengan suasana yang syahdu dan penuh harap.','e621a310e296cb6530648abf5e8d1d6a.webp',1049,748,'2026-08-22 01:47:38','2026-08-22 09:22:40'),(28,'Penanda di Antara Tumpukan','Ahmad Saihu','2026','Rambu peringatan pekerja berdiri kecil di antara gulungan kain besar yang menumpuk tinggi. Digambar dengan pensil hitam-putih yang tekstural, karya ini mengangkat skala industri tekstil dan posisi kecil manusia di dalamnya.','ef6bcbf781c6ac4ba75e9d663d53f413.webp',1439,1031,'2026-08-22 01:48:33','2026-08-22 09:22:41'),(29,'Bernomor','Ahmad Saihu','2026','Deretan kaki telanjang tergantung dengan angka merah tertulis di betis. Komposisi close-up yang sunyi namun mengusik, mengundang perenungan tentang identitas yang direduksi menjadi angka.','3b029de0e0e56d5a2a0cafe89c8c21b8.webp',1331,1337,'2026-08-22 02:03:01','2026-08-22 09:22:41'),(30,'Menyembunyikan Wajah','Ahmad Saihu','2026','Seorang anak duduk meringkuk menarik kerah bajunya menutupi wajah, hanya menyisakan mata yang mengintip. Latar warna pastel yang riang berbanding terbalik dengan gestur menarik diri dan waspada.','dff427065a4cb8c17c18e0a0557cdf4e.webp',1527,1920,'2026-08-22 02:04:36','2026-08-22 09:22:41'),(31,'Terbalik','Ahmad Saihu','2026','Seorang anak berbaring dengan kaki menjulang ke atas dan wajah menghadap ke bawah, seolah dunia dilihat dari sudut pandang yang terbalik — polah kanak-kanak yang jujur dan lepas.','1c8b193b736bae4ef1547c7ff7554761.webp',1509,1920,'2026-08-22 02:05:05','2026-08-22 09:22:41'),(32,'Dalam Diam','Ahmad Saihu','2026','Potret seorang perempuan menunduk dengan rambut disanggul, mengenakan busana merah, disinari cahaya lembut dari atas dengan latar biru bertekstur. Suasana hening dan reflektif mendominasi karya ini.','e04609c3b5881ad21a791670f56cabff.webp',1280,1280,'2026-08-22 02:05:32','2026-08-22 09:22:41'),(33,'Telur di Rimba Sunyi','Ahmad Saihu','2026','Sekelompok kecil pengembara berjalan mendekati bongkahan batu raksasa berbentuk telur di tengah hutan berkabut. Digarap monokrom, karya ini membangun suasana mitos dan misteri purba.','0d864c20baa060587b2630429f614fbb.webp',1280,1075,'2026-08-22 02:06:00','2026-08-22 09:22:42'),(34,'Terpejam','Ahmad Saihu','2026','Potret perempuan dengan mata terpejam dan rona merah di kelopak mata, rambut tergerai menutupi wajah. Latar abu kebiruan yang tenang membingkai ekspresi introspektif yang dalam.','32f934ecb96640103381e97161916f41.webp',1123,1600,'2026-08-22 02:06:23','2026-08-22 09:22:42'),(35,'test','Ahmad Saihu','2026','test','bff0e118e6fa38dd713d372bde4f61c7.webp',1280,1075,'2026-08-22 08:35:17','2026-08-22 09:22:42');
